<script lang="ts">
  import type { Snippet } from 'svelte'; import { ExternalLink } from '@lucide/svelte'; import { cn } from '../../utils.js'; import { safeExternalUrl } from './providers.js'; import { useOpenInContext } from './context.svelte.js';
  let { href, label, class: className = '', children, disabled = false, ...rest }: { href?: string; label?: string; class?: string; children?: Snippet; disabled?: boolean; [key: string]: unknown } = $props(); const context = useOpenInContext(); const safeHref = $derived(href ? safeExternalUrl(href) : undefined);
</script>
{#if safeHref && !disabled}<a class={cn('flex items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:outline-ring', className)} href={safeHref} target="_blank" rel="external noopener noreferrer" role="menuitem" onclick={() => context.setOpen(false)} {...rest}><span class="min-w-0 flex-1">{#if children}{@render children()}{:else}{label ?? safeHref}{/if}</span><ExternalLink size={14} class="shrink-0" aria-hidden="true" /></a>{:else}<button type="button" class={cn('flex items-center gap-2 rounded-sm px-2 py-1.5 text-left text-sm hover:bg-accent hover:text-accent-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:opacity-50', className)} role="menuitem" {disabled} onclick={() => context.setOpen(false)} {...rest}><span class="min-w-0 flex-1">{#if children}{@render children()}{:else}{label ?? 'Menu item'}{/if}</span></button>{/if}
